<script setup lang="ts">
import {computed,ref,watch,onMounted,onUnmounted,nextTick} from 'vue';
import type {Answers,ReadingExam,ReadingRecord,ReadingResult,Question} from './model';
import {gradeExam} from './grading';
import {readingWords,saveDraft,loadDraft,clearDraft,saveRecord,readingStorageWarning} from './storage';
import WordDialog from './WordDialog.vue';
const clone = <T,>(value:T):T => JSON.parse(JSON.stringify(value));
const props=defineProps<{exam:ReadingExam;record?:ReadingRecord}>();const emit=defineEmits<{back:[]}>();
const draft=props.record?undefined:loadDraft(props.exam.id);
const answers=ref<Answers>(clone(props.record?.answers||draft?.answers||{}));
const seconds=ref(props.record?.seconds||draft?.seconds||0);const sessionId=draft?.sessionId||crypto.randomUUID();
const result=ref<ReadingResult|undefined>(props.record?.result);const recorded=ref(!!props.record);const message=ref(draft?'已恢复上次的答案和用时。':'答案会自动保存在当前浏览器。');const confirmSubmit=ref(false);
const selected=ref<{word:string;example:string;left:number;top:number}>();const addingWord=ref<{word:string;example:string}>();const content=ref<HTMLElement>();
const title=ref<HTMLElement>();let timer:ReturnType<typeof setInterval>;let selectionTimer:ReturnType<typeof setTimeout>;let activeAt=Date.now();
const questions=computed(()=>props.exam.groups.flatMap(g=>g.questions));
const answered=computed(()=>questions.value.filter(q=>{const a=answers.value[q.id];return Array.isArray(a)?a.length>0:typeof a==='string'&&!!a.trim();}).reduce((sum,q)=>sum+q.points,0));
const clock=computed(()=>`${Math.floor(seconds.value/60).toString().padStart(2,'0')}:${(seconds.value%60).toString().padStart(2,'0')}`);
function persist(){if(!result.value)saveDraft({version:1,examId:props.exam.id,sessionId,answers:answers.value,seconds:seconds.value,updatedAt:new Date().toISOString()});}
watch(answers,persist,{deep:true});
function tick(){const now=Date.now();if(!result.value&&document.visibilityState==='visible'){seconds.value+=Math.max(0,Math.floor((now-activeAt)/1000));}activeAt=now;persist();}
function visibility(){activeAt=Date.now();persist();}
function textAnswer(id:string,event:Event){answers.value[id]=(event.target as HTMLInputElement).value;}
function choose(q:Question,value:string){if(result.value)return;answers.value[q.id]=answers.value[q.id]===value?'':value;}
function toggle(q:Question,value:string){if(result.value)return;const current=Array.isArray(answers.value[q.id])?[...answers.value[q.id] as string[]]:[];if(current.includes(value))answers.value[q.id]=current.filter(v=>v!==value);else if(current.length<(q.selectionCount||q.points))answers.value[q.id]=[...current,value];}
function selectedChoice(q:Question,value:string){const a=answers.value[q.id];return Array.isArray(a)?a.includes(value):a===value;}
function submission(){result.value=gradeExam(props.exam,answers.value);confirmSubmit.value=false;saveResult();nextTick(()=>document.getElementById('rp-result')?.focus());}
function saveResult(){if(!result.value)return;recorded.value=saveRecord({id:sessionId,examId:props.exam.id,title:props.exam.title,date:new Date().toISOString(),seconds:seconds.value,source:props.exam.source,result:result.value,answers:clone(answers.value),exam:clone(props.exam)});if(recorded.value){clearDraft(props.exam.id);message.value='结果已保存，可以在练习记录中回看。';}else message.value='结果尚未保存，请导出数据或释放存储空间后重试。';}
function getSelection(){const selection=window.getSelection();if(!selection||selection.isCollapsed||!selection.rangeCount||!content.value?.contains(selection.anchorNode)||!content.value?.contains(selection.focusNode)){selected.value=undefined;return;}const text=selection.toString().replace(/\s+/g,' ').trim().replace(/^[^a-zA-Z]+|[^a-zA-Z]+$/g,'');if(!/^[a-zA-Z]+(?:['’\-][a-zA-Z]+)*(?: [a-zA-Z]+(?:['’\-][a-zA-Z]+)*){0,4}$/.test(text)||text.length>80){selected.value=undefined;return;}const element=selection.anchorNode?.parentElement;if(element?.closest('input,textarea,button,select'))return;const rect=selection.getRangeAt(0).getBoundingClientRect();const context=element?.closest('p,li,td,th,blockquote')?.textContent||element?.textContent||text;selected.value={word:text,example:context.replace(/\s+/g,' ').trim().slice(0,1200),left:Math.max(12,Math.min(window.innerWidth-188,rect.left)),top:Math.max(8,Math.min(window.innerHeight-52,rect.bottom+8))};}
function selectionChanged(){clearTimeout(selectionTimer);selectionTimer=setTimeout(getSelection,120);}
function addSelected(){if(selected.value){addingWord.value={word:selected.value.word,example:selected.value.example};selected.value=undefined;window.getSelection()?.removeAllRanges();}}
function marked(html:string){if(!readingWords.value.length)return html;const doc=new DOMParser().parseFromString(html,'text/html');const keys=readingWords.value.map(w=>w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).sort((a,b)=>b.length-a.length);const pattern=new RegExp(`\\b(${keys.join('|')})\\b`,'gi');const walker=doc.createTreeWalker(doc.body,NodeFilter.SHOW_TEXT);const nodes:Text[]=[];while(walker.nextNode())nodes.push(walker.currentNode as Text);for(const node of nodes){const text=node.textContent||'';pattern.lastIndex=0;const matches=[...text.matchAll(pattern)];if(!matches.length)continue;const fragment=doc.createDocumentFragment();let at=0;for(const match of matches){fragment.append(text.slice(at,match.index));const mark=doc.createElement('mark');mark.className='rp-saved-word';mark.title='已加入阅读生词库';mark.textContent=match[0];fragment.append(mark);at=match.index!+match[0].length;}fragment.append(text.slice(at));node.replaceWith(fragment);}return doc.body.innerHTML;}
const markedPassage=computed(()=>marked(props.exam.passageHtml));
const markedGroups=computed(()=>props.exam.groups.map(group=>({...group,instructionsHtml:marked(group.instructionsHtml),questions:group.questions.map(q=>({...q,promptHtml:marked(q.promptHtml)}))})));
function closeWord(){addingWord.value=undefined;title.value?.focus({preventScroll:true});}
onMounted(()=>{title.value?.focus({preventScroll:true});timer=setInterval(tick,1000);document.addEventListener('selectionchange',selectionChanged);document.addEventListener('visibilitychange',visibility);window.addEventListener('pagehide',persist);});
onUnmounted(()=>{persist();clearInterval(timer);clearTimeout(selectionTimer);document.removeEventListener('selectionchange',selectionChanged);document.removeEventListener('visibilitychange',visibility);window.removeEventListener('pagehide',persist);});
</script>
<template><section class="rp-practice"><header class="rp-practice-header"><div><button class="rp-link" @click="emit('back')">← 返回题库</button><h1 ref="title" tabindex="-1">{{exam.title}}</h1><p class="rp-caption">{{exam.part}} · {{exam.questionCount}} 题 · {{exam.source.label}}</p></div><div class="rp-practice-tools"><span class="rp-timer" aria-label="练习用时">{{clock}}</span><span class="rp-caption">已答 {{answered}} / {{exam.questionCount}}</span><button v-if="!result" class="rp-button" @click="confirmSubmit=true">提交答案</button></div></header><p class="rp-practice-hint" role="status">{{message}} 选中文章或题目中的英文单词，可加入生词库。</p><section v-if="result" id="rp-result" class="rp-result-banner" tabindex="-1"><div><span class="rp-eyebrow">练习结果</span><h2>{{result.earned}} <small>/ {{result.total}}</small></h2></div><p>正确率 {{result.percentage}}% · 本页展示你的作答和参考答案</p><button v-if="!recorded" class="rp-button" @click="saveResult">重新保存结果</button></section><div ref="content" class="rp-reading-layout" @mouseup="getSelection" @keyup="getSelection"><article class="rp-reading-pane"><div class="rp-pane-heading"><span class="rp-eyebrow">READING PASSAGE</span><span class="rp-caption">黄色标记为已收藏生词</span></div><div class="rp-prose" v-html="markedPassage"></div><details class="rp-source-note"><summary>文章与题目来源</summary><p>{{exam.source.label}}</p><p>{{exam.source.reference}}</p><a v-if="exam.source.url" :href="exam.source.url" target="_blank" rel="noopener noreferrer">查看来源网站 ↗</a></details></article><section class="rp-questions-pane" aria-label="阅读题目"><article v-for="group in markedGroups" :key="group.id" class="rp-question-group"><header class="rp-row"><h2>{{group.title}}</h2><span class="rp-caption">{{group.questions.reduce((n,q)=>n+q.points,0)}} 题</span></header><div class="rp-prose rp-question-content" v-html="group.instructionsHtml"></div><p class="rp-caption">请在下方答题区填写，方括号为原文题号。</p><fieldset v-for="q in group.questions" :id="`answer-${q.id}`" :key="q.id" class="rp-answer" :disabled="!!result"><legend>第 {{q.label}} 题 <span v-if="q.kind==='multi'" class="rp-caption">（选 {{q.selectionCount}} 项，{{q.points}} 分）</span></legend><div v-if="q.promptHtml" class="rp-prose" v-html="q.promptHtml"></div><label v-if="q.kind==='text'" class="rp-field"><span class="rp-caption">{{q.maxWords?`最多 ${q.maxWords} 个英文词 / 数字`:'填写英文答案'}}</span><input :aria-label="`第 ${q.label} 题答案`" :value="answers[q.id]||''" maxlength="200" autocomplete="off" spellcheck="false" @input="textAnswer(q.id,$event)"></label><label v-else-if="q.kind==='matching'" class="rp-field"><span class="rp-caption">选择对应选项</span><select :aria-label="`第 ${q.label} 题答案`" :value="answers[q.id]||''" @change="textAnswer(q.id,$event)"><option value="">请选择</option><option v-for="o in q.options" :key="o.value" :value="o.value">{{o.label}}</option></select></label><div v-else class="rp-answer-options"><button v-for="o in q.options" :key="o.value" type="button" :class="['rp-option',{selected:selectedChoice(q,o.value)}]" :aria-pressed="selectedChoice(q,o.value)" :disabled="!!result||(q.kind==='multi'&&!selectedChoice(q,o.value)&&((answers[q.id] as string[]||[]).length>=(q.selectionCount||q.points)))" @click="q.kind==='multi'?toggle(q,o.value):choose(q,o.value)">{{o.label}}</button></div><div v-if="result" :class="['rp-answer-result',result.items.find(i=>i.id===q.id)?.status]"><strong>{{ {correct:'正确',partial:'部分正确',incorrect:'错误',unanswered:'未作答'}[result.items.find(i=>i.id===q.id)?.status||'unanswered'] }}</strong><p>你的答案：{{Array.isArray(answers[q.id])?(answers[q.id] as string[]).join('、'):answers[q.id]||'未填写'}}</p><p>参考答案：{{(q.correctSet||q.accepted).join(q.kind==='multi'?'、':' / ')}}</p><p v-if="q.kind==='multi'">得分 {{result.items.find(i=>i.id===q.id)?.earned}} / {{q.points}}</p></div></fieldset></article></section></div><button v-if="selected" class="rp-selection-action" :style="{left:selected.left+'px',top:selected.top+'px'}" @pointerdown.prevent @click="addSelected">＋ 加入生词库</button><WordDialog v-if="addingWord" :word="addingWord.word" :example="addingWord.example" :exam="exam" @close="closeWord"/><div v-if="confirmSubmit" class="rp-modal-backdrop" @click.self="confirmSubmit=false"><section class="rp-dialog" role="dialog" aria-modal="true" aria-labelledby="submit-title"><h2 id="submit-title">提交本次阅读练习？</h2><p>{{answered<exam.questionCount?`还有 ${exam.questionCount-answered} 题未完成，未作答题目计为 0 分。`:'所有题目已填写，提交后可查看参考答案。'}}</p><p v-if="readingStorageWarning" class="rp-error">{{readingStorageWarning}}</p><div class="rp-row rp-actions"><button class="rp-button secondary" @click="confirmSubmit=false">继续答题</button><button class="rp-button" @click="submission">确认提交</button></div></section></div></section></template>
